// Private event admission combines the existing same-edge sample and
// configuration vetoes. Real render/config broadcasts keep their owners.
// Unknown controls use the original complete four-state fence.
reg combined_event_admission;
always @* begin
    combined_event_admission=sample_ce_o ||
        (!core_rate_busy && (core_config || external_history));
    case (^{rst_ni,active,external_busy,core_fault,config_valid_i,
            history_clear_i,core_rate_busy,cancel_delivery_pending,
            render_request_i,response_sent,cancelled,held_rate,core_rate})
        1'b0,1'b1: combined_event_admission=!core_rate_busy &&
            ((!active && !external_busy && !core_fault &&
              (config_valid_i || history_clear_i ||
               (rst_ni && !cancel_delivery_pending && render_request_i))) ||
             (active && !response_sent && !cancelled && held_rate!=core_rate));
        default: begin end
    endcase
end
wire requested_rate=external_config ? config_rate_44100_i : accepted ? render_44k1_i : held_rate;

